// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	for (let element of document.getElementsByClassName("p5Canvas")) {
    element.addEventListener("contextmenu", (e) => e.preventDefault());
  }
	background(0);
	frameRate(240);

	LORENZ = new Lorenz(100);
}

function mouseDragged() {LORENZ.Pan();}
function mouseWheel(e) {LORENZ.Zoom(e.delta);}

function draw() {
	clear();
	LORENZ.Update();
	LORENZ.Blit();
}

// === Tab: point ===
class Point
{
	constructor()
	{
		this.x = 2*random()-1;
		this.y = 2*random()-1;
		this.z = 2*random()-1;
		this.colour = RandomColour();
	}

	Update(dt, sigma, rho, beta)
	{
		let dxdt = sigma*(this.y-this.x);
		let dydt = this.x*(rho-this.z) - this.y;
		let dzdt = this.x * this.y - beta*this.z;

		this.x += dt*dxdt;
		this.y += dt*dydt;
		this.z += dt*dzdt;
	}
}

// === Tab: lorenz ===
class Lorenz
{
	constructor(numberOfPoints)
	{
		//init points
		this.points = [];
		this.numberOfPoints = numberOfPoints;
		for (let i = 0; i < numberOfPoints; i++)
			this.points.push(new Point());

		//differential parameters
		this.sigma = 10;
		this.rho = 28;
		this.beta = 8/3;
		this.dt = 0.01;

		//buffer
		this.buffer = createGraphics(width, height*1.1);
		this.buffer.background(0);
		this.buffer.translate(width/2, height);
		this.buffer.scale(9,-9);

		//draw params
		this.strokeWeight = 0.1;

		//axis params
		this.horizontal = "x";
		this.vertical = "z";
	}

	Zoom(dt)
	{
		this.buffer.scale(dt>0 ? 1.01 : 0.99);
	}
	Pan()
	{
		if (mouseButton != RIGHT) return;
		let dx = (window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
		let dy = (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
		this.buffer.translate(-dx,dy);
	}

	Reset(numberOfPoints)
	{
		//clear buffer
		this.buffer.background(0);

		//init points
		this.points = [];
		for (let i = 0; i < numberOfPoints; i++)
			this.points.push(new Point());
	}

	Update()
	{
		this.buffer.background(0,0,0,5);

		this.buffer.strokeWeight(this.strokeWeight);
		for (let i = 0; i < this.points.length; i++)
		{
			//get old pos
			let old = {"x":this.points[i].x, "y":this.points[i].y, "z":this.points[i].z};
			//update
			this.points[i].Update(this.dt, this.sigma, this.rho, this.beta);
			//draw line
			this.buffer.stroke(this.points[i].colour[0], this.points[i].colour[1], this.points[i].colour[2]);
			this.buffer.line(old[this.horizontal], old[this.vertical], this.points[i][this.horizontal], this.points[i][this.vertical]);
		}
	}

	Blit()
	{
		image(this.buffer, 0, 0, width, height);
	}
}

// === Tab: colours ===
function RandomColour() {
	return [int(random()*255), int(random()*255), int(random()*255)];
}

// === Tab: gui ===
var settings = QuickSettings.create(0, 0, "Settings", null);
settings.addNumber("σ", -Infinity, Infinity, 10, 0, (val)=>{
	LORENZ.sigma = float(settings.getValue("σ"));
});
settings.addNumber("⍴", -Infinity, Infinity, 28, 0, (val)=>{
	LORENZ.rho = float(settings.getValue("⍴"));
});
settings.addNumber("β", -Infinity, Infinity, 8/3, 0, (val)=>{
	LORENZ.sigma = float(settings.getValue("β"));
});
settings.addNumber("No. points", 1, Infinity, 100, 1, null);
settings.addRange("Timestep", 0, 0.02, 0.01, 0.001, (val)=>{
	LORENZ.dt = float(settings.getValue("Timestep"));
});
settings.addRange("Thickness", 0, 0.5, 0.1, 0.001, (val)=>{
	LORENZ.strokeWeight = float(settings.getValue("Thickness"));
});
settings.addDropDown("Horizontal Axis", ["x","y","z"], (val)=>{
	LORENZ.horizontal = val.value;
});
settings.addDropDown("Vertical Axis", ["z","x","y"], (val)=>{
	LORENZ.vertical = val.value;
});
settings.addButton("Reset", ()=>{
	let p = (int(settings.getValue("No. points")));
	LORENZ.Reset(p);
});

